typedef struct {
    int  (*read)(void *state, char *buf, size_t n);   /* required step */
    void (*transform)(void *state, char *buf);       /* required step */
    void (*emit)(void *state, const char *out);      /* hook: may be NULL */
} processor_ops;
void processor_run(const processor_ops *ops, void *state, size_t n) {
    char buf[256];
    if (!ops || !ops->read || !ops->transform) return;  /* validate the table */
    if (ops->read(state, buf, n) < 0) return;           /* step 1 */
    ops->transform(state, buf);                         /* step 2 */
    if (ops->emit) ops->emit(state, buf);               /* optional hook */
}
